import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
// 가정: 과세 세액은 공급가액의 10%이며 반올림 오차 1원까지 허용한다.
const TAX_RATE = 0.1;
const TAX_TOLERANCE = 1;

const SELECT_ROW =
  'SELECT t.tax_invoice_id AS "taxInvoiceId", ' +
  't.partner_id AS "partnerId", ' +
  'p.partner_id AS "partnerFound", ' +
  't.expense_resolution_id AS "expenseResolutionId", ' +
  't.tax_type AS "taxType", ' +
  't.issue_date AS "issueDate", ' +
  't.supply_amount AS "supplyAmount", ' +
  't.tax_amount AS "taxAmount", ' +
  't.approval_number AS "approvalNumber", ' +
  't.journal_status AS "journalStatus" ' +
  'FROM tax_invoice t ' +
  'LEFT JOIN partner p ON p.partner_id = t.partner_id ' +
  'WHERE t.tax_invoice_id = CAST(:id AS bigint) ' +
  'FOR UPDATE OF t';

function idsOf(data: Record<string, unknown>): number[] {
  const raw = data['taxInvoiceIds'];
  if (raw === undefined || raw === null || (Array.isArray(raw) && raw.length === 0)) {
    throw new ApiError(422, 'TAX_INVOICE_NOT_SELECTED', '대상 세금계산서를 선택해 주세요.');
  }
  if (!Array.isArray(raw)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '세금계산서 ID 목록 형식이 올바르지 않습니다.');
  }
  const ids: number[] = [];
  for (const v of raw) {
    if (typeof v !== 'number' || !Number.isInteger(v) || v <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '세금계산서 ID는 양의 정수여야 합니다.');
    }
    if (!ids.includes(v)) {
      ids.push(v);
    }
  }
  return ids;
}

async function loadRow(db: any, id: number): Promise<Record<string, any>> {
  const rows = await db.query(SELECT_ROW, { id: id });
  if (rows.length === 0) {
    throw new ApiError(404, 'TAX_INVOICE_NOT_FOUND', '세금계산서를 찾을 수 없습니다. (ID ' + id + ')');
  }
  return rows[0];
}

// 검증 기준: 필수 항목과 금액 정합성 (결정)
function errorsOf(row: Record<string, any>): string[] {
  const errors: string[] = [];
  const supply = Number(row['supplyAmount']);
  const tax = Number(row['taxAmount']);
  if (row['partnerFound'] === null || row['partnerFound'] === undefined) {
    errors.push('거래처 기준정보가 없습니다.');
  }
  if (!row['issueDate']) {
    errors.push('작성일자가 없습니다.');
  }
  // 가정: 국세청 승인번호를 필수 항목으로 본다.
  if (!row['approvalNumber'] || String(row['approvalNumber']).trim() === '') {
    errors.push('국세청 승인번호가 없습니다.');
  }
  // 가정: 전표는 결의서 기준으로 만들어지므로 결의서 연결을 필수 항목으로 본다.
  if (row['expenseResolutionId'] === null || row['expenseResolutionId'] === undefined) {
    errors.push('연결된 결의서가 없습니다.');
  }
  if (!Number.isFinite(supply) || !Number.isFinite(tax)) {
    errors.push('공급가액 또는 세액이 숫자가 아닙니다.');
  } else if (row['taxType'] === 'EXEMPT') {
    if (tax !== 0) {
      errors.push('면세 세금계산서의 세액은 0이어야 합니다.');
    }
  } else if (Math.abs(tax - Math.round(supply * TAX_RATE)) > TAX_TOLERANCE) {
    errors.push('공급가액과 세액이 맞지 않습니다.');
  }
  return errors;
}

@Controller('api/v1')
export class FnSfr00803Controller {
  @Post('/tax-invoices/validate')
  @HttpCode(200)
  async validateTaxInvoices(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const ids = idsOf(data);
    return transaction(async (db) => {
      const results: Record<string, unknown>[] = [];
      for (const id of ids) {
        const row = await loadRow(db, id);
        const errors = errorsOf(row);
        results.push({
          taxInvoiceId: id,
          valid: errors.length === 0,
          errors: errors,
        });
      }
      return { results: results };
    });
  }

  @Post('/tax-invoices/create-journal-entries')
  @HttpCode(200)
  async createJournalEntriesFromTaxInvoices(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const ids = idsOf(data);
    return transaction(async (db) => {
      const results: Record<string, unknown>[] = [];
      for (const id of ids) {
        const row = await loadRow(db, id);
        if (row['journalStatus'] !== 'UNPROCESSED') {
          throw new ApiError(409, 'TAX_INVOICE_ALREADY_PROCESSED', '이미 전표처리된 세금계산서입니다. (ID ' + id + ')');
        }
        const errors = errorsOf(row);
        if (errors.length > 0) {
          throw new ApiError(422, 'TAX_INVOICE_VALIDATION_FAILED', '검증 오류가 있어 전표처리할 수 없습니다. (ID ' + id + '): ' + errors.join(' '));
        }
        const created = await db.query(
          'INSERT INTO journal_entry (expense_resolution_id, entry_date, status, total_debit_amount, total_credit_amount, summary, created_at, updated_at) ' +
            "SELECT t.expense_resolution_id, t.issue_date, '신청', t.supply_amount + t.tax_amount, t.supply_amount + t.tax_amount, t.item_description, now(), now() " +
            'FROM tax_invoice t WHERE t.tax_invoice_id = CAST(:id AS bigint) ' +
            'RETURNING journal_entry_id AS "journalEntryId"',
          { id: id },
        );
        const journalEntryId = created[0]['journalEntryId'];
        const changed = await db.execute(
          "UPDATE tax_invoice SET journal_status = 'PROCESSED', journal_entry_id = CAST(:journalEntryId AS bigint), updated_at = now() " +
            "WHERE tax_invoice_id = CAST(:id AS bigint) AND journal_status = 'UNPROCESSED'",
          { id: id, journalEntryId: journalEntryId },
        );
        if (changed !== 1) {
          throw new ApiError(409, 'TAX_INVOICE_ALREADY_PROCESSED', '이미 전표처리된 세금계산서입니다. (ID ' + id + ')');
        }
        results.push({
          taxInvoiceId: id,
          journalEntryId: journalEntryId,
          success: true,
        });
      }
      return { results: results };
    });
  }
}

