import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  Num,
  Pager,
  RefName,
  Select,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

type Mode = 'validate' | 'journal' | null;

export default function FnSfr00803Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [draft, setDraft] = useState<Row>({});
  const [query, setQuery] = useState<Row>({});
  const [selected, setSelected] = useState<number[]>([]);
  const [mode, setMode] = useState<Mode>(null);
  const [results, setResults] = useState<Row[]>([]);
  const [pickError, setPickError] = useState('');

  const { data, error, loading, reload } = useData<Page>(
    () =>
      call<Page>('GET', '/tax-invoices', role, undefined, {
        page: page,
        size: SIZE,
        startDate: query.startDate,
        endDate: query.endDate,
        taxType: query.taxType,
      }),
    [page, query],
  );

  function toggle(id: number) {
    setSelected(selected.includes(id) ? selected.filter((v) => v !== id) : [...selected, id]);
  }

  function open(next: Mode) {
    if (selected.length === 0) {
      setPickError('대상 세금계산서를 먼저 선택해 주세요.');
      return;
    }
    setPickError('');
    setResults([]);
    setMode(next);
  }

  function close() {
    setMode(null);
    setResults([]);
  }

  async function runValidate() {
    const res = await call<{ results: Row[] }>('POST', '/tax-invoices/validate', role, { taxInvoiceIds: selected });
    setResults(res.results);
    notify('검증했습니다.');
  }

  async function runJournal() {
    const res = await call<{ results: Row[] }>('POST', '/tax-invoices/create-journal-entries', role, { taxInvoiceIds: selected });
    setResults(res.results);
    setSelected([]);
    notify('전표처리했습니다.');
    reload();
  }

  const columns = [
    {
      key: 'select',
      label: '선택',
      render: (row: Row) =>
        row.journalStatus === 'UNPROCESSED' ? (
          <input
            type="checkbox"
            checked={selected.includes(Number(row.taxInvoiceId))}
            onChange={() => toggle(Number(row.taxInvoiceId))}
            onClick={(e) => e.stopPropagation()}
          />
        ) : null,
    },
    { key: 'partnerId', label: '거래처', render: (row: Row) => <RefName table="partner" role={role} value={row.partnerId} /> },
    { key: 'issueDate', label: '작성일자', render: (row: Row) => <DateText value={row.issueDate} /> },
    { key: 'supplyAmount', label: '공급가액', render: (row: Row) => <Num value={row.supplyAmount} /> },
    { key: 'journalStatus', label: '전표처리 상태', render: (row: Row) => <Badge value={row.journalStatus} /> },
  ];

  const resultColumns = [
    { key: 'taxInvoiceId', label: '세금계산서 번호' },
    {
      key: 'valid',
      label: '결과',
      render: (row: Row) => (row.journalEntryId !== undefined ? '전표 ' + String(row.journalEntryId) + ' 생성' : row.valid ? '정상' : '오류'),
    },
    {
      key: 'errors',
      label: '오류 사유',
      render: (row: Row) => (Array.isArray(row.errors) && row.errors.length > 0 ? row.errors.join(' ') : '-'),
    },
  ];

  return (
    <div className="doc">
      <section className="box">
        <h2>전자세금계산서 현황</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setSelected([]);
            setQuery(draft);
          }}
          onReset={() => {
            setPage(0);
            setSelected([]);
            setDraft({});
            setQuery({});
          }}
        >
          <Field label="조회 기간 시작일">
            <DateInput value={draft.startDate} onChange={(v) => setDraft({ ...draft, startDate: v })} />
          </Field>
          <Field label="조회 기간 종료일">
            <DateInput value={draft.endDate} onChange={(v) => setDraft({ ...draft, endDate: v })} />
          </Field>
          <Field label="과세·면세 구분">
            <Select
              value={draft.taxType}
              onChange={(v) => setDraft({ ...draft, taxType: v })}
              options={[
                ['TAXABLE', '과세'],
                ['EXEMPT', '면세'],
              ]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button className="ghost" onClick={() => open('validate')}>검증</button>
          <button onClick={() => open('journal')}>전표처리</button>
          <button className="ghost" onClick={() => window.print()}>출력</button>
        </Band>
        {pickError ? <ErrorText text={pickError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        {loading ? <p>불러오는 중입니다.</p> : null}
        <DataTable columns={columns} rows={data?.items ?? []} empty="조회된 세금계산서가 없습니다. 조회 기간을 바꿔 다시 검색해 주세요." />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>

      {mode === 'validate' ? (
        <Drawer title="세금계산서 검증" onClose={close}>
          <Form onSubmit={runValidate} submit="검증 실행" note={'선택한 ' + selected.length + '건의 필수 항목과 금액 정합성을 검증합니다.'}>
            {results.length > 0 ? <DataTable columns={resultColumns} rows={results} /> : null}
          </Form>
        </Drawer>
      ) : null}

      {mode === 'journal' ? (
        <Drawer title="전표처리" onClose={close}>
          <Form
            onSubmit={runJournal}
            submit="전표처리 실행"
            note={'선택한 ' + selected.length + '건을 전표처리합니다. 처리한 세금계산서는 다시 전표처리할 수 없습니다.'}
          >
            {results.length > 0 ? <DataTable columns={resultColumns} rows={results} /> : null}
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
